// Generated by scripts/gen-manifest.ts. Do not edit by hand.
// Each tool is a chunk of its own. Nothing here runs until a session needs it.
import type { AnyToolModule } from './registry';

const loaders: Record<string, () => Promise<AnyToolModule>> = {
  bag: () => import('../tools/bag/tool.svelte.ts').then((module) => module.default),
  bracket: () => import('../tools/bracket/tool.svelte.ts').then((module) => module.default),
  buzzer: () => import('../tools/buzzer/tool.svelte.ts').then((module) => module.default),
  coin: () => import('../tools/coin/tool.svelte.ts').then((module) => module.default),
  counters: () => import('../tools/counters/tool.svelte.ts').then((module) => module.default),
  custom: () => import('../tools/custom/tool.svelte.ts').then((module) => module.default),
  decks: () => import('../tools/decks/tool.svelte.ts').then((module) => module.default),
  demo: () => import('../tools/demo/tool.svelte.ts').then((module) => module.default),
  dice: () => import('../tools/dice/tool.svelte.ts').then((module) => module.default),
  draft: () => import('../tools/draft/tool.svelte.ts').then((module) => module.default),
  lives: () => import('../tools/lives/tool.svelte.ts').then((module) => module.default),
  pick: () => import('../tools/pick/tool.svelte.ts').then((module) => module.default),
  prompts: () => import('../tools/prompts/tool.svelte.ts').then((module) => module.default),
  reveal: () => import('../tools/reveal/tool.svelte.ts').then((module) => module.default),
  rules: () => import('../tools/rules/tool.svelte.ts').then((module) => module.default),
  score: () => import('../tools/score/tool.svelte.ts').then((module) => module.default),
  script: () => import('../tools/script/tool.svelte.ts').then((module) => module.default),
  splits: () => import('../tools/splits/tool.svelte.ts').then((module) => module.default),
  timer: () => import('../tools/timer/tool.svelte.ts').then((module) => module.default),
  turns: () => import('../tools/turns/tool.svelte.ts').then((module) => module.default),
  words: () => import('../tools/words/tool.svelte.ts').then((module) => module.default),
};

export function hasTool(id: string): boolean {
  return Object.prototype.hasOwnProperty.call(loaders, id);
}

/** Loads one tool on demand. Rejects for an id this build does not ship. */
export function loadTool(id: string): Promise<AnyToolModule> {
  const load = loaders[id];
  return load ? load() : Promise.reject(new Error(`Unknown tool "${id}"`));
}
